  ('zcrm_5797994000003664027', 'Amptify', 'Amptify', 'Angjelo Terolli', 'Chris Cardinal', 'Amptify engages in the provision of hearing healthcare services using a technology platform via mobile devices, the internet, video and phone. Founded by a world-renowned aural rehabilitation research team as a university spin-off from the Audiovisual Speech Perception Laboratory at the Washington University in St. Louis School of Medicine,', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Angjelo Terolli', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-03 12:28:48', '2026-02-03 12:28:48', '2026-02-03 12:28:48'),
  ('zcrm_5797994000003664062', 'Neusleep', 'Neusleep', 'Angjelo Terolli', 'Colin Budries', 'Neusleep is a wearable device that directly induces and improves natural sleep through personalized nerve stimulation. It induces and improves sleep by enhancing biological rhythms.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Angjelo Terolli', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-03 12:54:46', '2026-02-03 12:54:47', '2026-02-03 12:54:47'),
  ('zcrm_5797994000003664110', 'SHRED', 'SHRED', 'Angjelo Terolli', 'Chris Yerga', 'SHRED is a technology company specializing in elite digital training experiences. SHRED offers personalized training programs for gym & home, step-by-step AI coaching and tracking, and friendly motivation from a hardworking community around the world.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Angjelo Terolli', 'Source', 'Sports & Wellness', 'Founder Communication (no response etc.)', NULL, '2026-02-04 06:49:16', '2026-03-05 17:49:16', '2026-03-05 17:49:16'),
  ('zcrm_5797994000003664145', 'Vitagene', 'Vitagene', 'Angjelo Terolli', 'Reza Malek', 'Vitagene leverages big data and machine learning to provide personalized, actionable diet, fitness, and supplement recommendations to its members.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Angjelo Terolli', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-04 07:08:25', '2026-02-04 07:08:25', '2026-02-04 07:08:25'),
  ('zcrm_5797994000003665044', 'Drive Health', 'Drive Health', 'Burhanudin Ayubali', 'Kevin Longoria', 'Developer of a healthcare technology platform designed to enhance patient engagement and care delivery. The company''s platform integrates AI-driven tools for enrollment, assessments, adherence, education, triage, and personalized care journeys, enabling healthcare providers to streamline operations, improve efficiency, and deliver better patient outcomes.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Reached Out', 'Burhanudin Ayubali', 'Source', NULL, NULL, NULL, '2026-02-03 18:21:30', '2026-02-03 18:21:30', NULL),
  ('zcrm_5797994000003665058', 'SMARTLENS', 'Smartlens', 'Burhanudin Ayubali', 'Savas Komban', 'Developer of a wearable device designed to prevent the progression of glaucoma and irreversible blindness. The company''s technology utilizes a microfluidic-based smart contact lens and a smartphone app powered to monitor intraocular pressure, clinical trials have demonstrated a strong correlation with office-based standard-of-care devices, positioning the company as the first to offer an accurate and convenient method for monitoring the risk and progression of glaucoma, enabling patients to get an efficient and convenient way of monitoring IOP at home.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Reached Out', 'Burhanudin Ayubali', 'Source', NULL, NULL, NULL, '2026-02-03 18:32:59', '2026-02-03 18:32:59', NULL),
  ('zcrm_5797994000003665072', 'Kompass diagnostics', 'Kompass Diagnostics', 'Burhanudin Ayubali', 'Mingoo Kim', 'Developer of a blood-based point-of-care hormone diagnostic device designed to support timely and accessible hormone monitoring for healthcare use. The company offers a portable, easy-to-use hormone monitor with lab-grade precision, enabling fertility care providers, patients, and related medical practitioners to track hormone levels remotely and improve treatment oversight.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Reached Out', 'Burhanudin Ayubali', 'Source', NULL, NULL, NULL, '2026-02-03 18:40:21', '2026-02-03 18:40:21', NULL),
  ('zcrm_5797994000003665098', 'Sonovascular', 'sonovascular', 'Burhanudin Ayubali', 'Luke Harada', 'Developer of a multi-mechanistic ultrasound-facilitated thrombectomy system designed for the treatment of arterial and venous thrombosis. The company''s system offers endovascular treatment of venous and arterial thrombosis, including deep vein thrombosis and pulmonary embolism, peripheral artery occlusion, and acute ischemic stroke, enabling patients to receive safe and effective treatment in the catheterization laboratory.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Reached Out', 'Burhanudin Ayubali', 'One Pager', NULL, NULL, NULL, '2026-02-03 18:49:55', '2026-02-27 07:23:42', '2026-02-27 07:23:42'),
  ('zcrm_5797994000003665117', '28bio', '28bio', 'Burhanudin Ayubali', 'None', 'Developer of a brain-on-a-chip platform designed to capture neurological processes in the brain and nervous system. The company''s platform utilizes tissue engineering, neural interfacing and artificial intelligence to measure clinically relevant electrophysiology data analyzed by models, enabling healthcare professionals to treat neurological diseases.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Reached Out', 'Burhanudin Ayubali', 'Source', NULL, NULL, NULL, '2026-02-03 19:10:51', '2026-02-03 19:10:51', NULL),
